def validate_items(items):
    if not items:
        raise ValueError("Items list cannot be empty")
    for item in items:
        if item['price'] < 0 or item['quantity'] < 0:
            raise ValueError("Price or quantity cannot be negative")

def calculate_totals(items, customer_type):
    subtotal = sum(item['price'] * item['quantity'] for item in items)
    tax_rate = 0.07 if customer_type == 'regular' else 0.05  # Example tax rates
    tax = subtotal * tax_rate
    total = subtotal + tax
    receipt = f"Subtotal: ${subtotal:.2f}, Tax: ${tax:.2f}"
    return {'total': total, 'receipt': receipt}

def format_receipt(items, total):
    formatted_items = "\n".join([f"{item['name']}: {item['quantity']} x ${item['price']:.2f}" for item in items])
    formatted_total = f"Total: ${total:.2f}"
    return f"{formatted_items}\n{formatted_total}"

def process_order(items, customer_type):
    validate_items(items)
    totals = calculate_totals(items, customer_type)
    receipt = format_receipt(items, totals['total'])
    return {'total': totals['total'], 'receipt': receipt}
